#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreDayLog: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CoreDayLog

    public static func lift(_ handle: UInt64) throws -> CoreDayLog {
        return CoreDayLog(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CoreDayLog) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreDayLog {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CoreDayLog, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreDayLog_lift(_ handle: UInt64) throws -> CoreDayLog {
    return try FfiConverterTypeCoreDayLog.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreDayLog_lower(_ value: CoreDayLog) -> UInt64 {
    return FfiConverterTypeCoreDayLog.lower(value)
}






/**
 * An open workspace database.
 *
 * Two connections. Every write, and most reads, go through `connection`,
 * whose `data_version` the apps poll. `reader` serves the reads a client
 * makes off its main thread (the next-up snapshot), so a main-thread read
 * does not queue behind them on one lock. It is `query_only` and never
 * holds a transaction open between calls, so under WAL each of its reads
 * sees every commit made before it began, the handle's own included, and it
 * cannot move the writer's `data_version`: reads do not commit.
 */
public protocol CoreWorkspaceProtocol: AnyObject, Sendable {
    
    /**
     * Every scope with instructions; see [`agent_instructions`].
     */
    func agentInstructions() throws  -> [AgentInstruction]
    
    /**
     * Brings in older instructions, outside the journal; see
     * [`import_agent_instructions`].
     */
    func importAgentInstructions(seeds: [AgentInstructionSeed], nowMs: Int64) throws  -> UInt32
    
    /**
     * Sets a scope's instructions as one "Edit Agent Instructions" step and
     * returns the text it holds now.
     */
    func setAgentInstructions(kind: AgentInstructionKind, id: String?, text: String, append: Bool, nowMs: Int64) throws  -> String
    
    /**
     * Board `key`'s columns over `list_ids`, and where its tasks are drawn.
     */
    func boardColumns(key: String, listIds: [String], nowMs: Int64, zone: String) throws  -> BoardColumns
    
    /**
     * Deletes a column, moving its tasks, as one "Delete Column" step.
     */
    func deleteBoardColumn(key: String, listIds: [String], columnId: String, toColumn: String?, nowMs: Int64) throws 
    
    /**
     * Makes a board's columns the default, as one "Make Default Columns" step.
     */
    func makeDefaultBoardColumns(key: String) throws 
    
    /**
     * Moves tasks into a column, editing the first to meet a rule column's
     * rules, as one "Move Task" step.
     */
    func moveToBoardColumn(key: String, taskIds: [String], columnId: String, nowMs: Int64, zone: String) throws 
    
    /**
     * Has a board follow the default columns again, as one "Reset Columns" step.
     */
    func resetBoardColumns(key: String) throws 
    
    /**
     * Saves a board's columns, moving cards out of a removed one, as one step.
     */
    func setBoardColumns(key: String, columns: [BoardColumn], movingTaskIds: [String], toColumn: String?, label: String, nowMs: Int64) throws 
    
    /**
     * Brings in an hour kept before the account had one; whether it did.
     */
    func adoptDayStartHour(hour: Int32, nowMs: Int64) throws  -> Bool
    
    /**
     * Starts the day if it has changed since the last reset; whether the
     * context was reset. Every client calls it when it evaluates.
     */
    func applyDayStart(workspaceId: String, nowMs: Int64, zone: String) throws  -> Bool
    
    /**
     * How each day starts.
     */
    func dayStartSettings() throws  -> DayStartSettings
    
    /**
     * Stores how each day starts; whether anything changed. Not an undo
     * step, like the rest of what holds now.
     */
    func setDayStartSettings(settings: DayStartSettings, nowMs: Int64, zone: String) throws  -> Bool
    
    /**
     * The workspace `workspace_id` written out as `format`, stamped
     * `exported_at_ms`; absent when there is no such workspace.
     */
    func exportWorkspace(workspaceId: String, format: ExportFormat, exportedAtMs: Int64) throws  -> String?
    
    /**
     * Creates a filter list as one "New Filter List" step.
     */
    func createFilterList(workspaceId: String, name: String, icon: String?, colorHex: String?, definition: FilterDefinition, nowMs: Int64) throws  -> FilterListRow
    
    /**
     * Deletes a filter list as one "Delete Filter List" step.
     */
    func deleteFilterList(id: String) throws 
    
    /**
     * One filter list, stored or built in.
     */
    func filterList(id: String) throws  -> FilterListRow?
    
    /**
     * A filter list's board over `list_ids`, as `combined_board` reads one.
     */
    func filterListBoard(definition: FilterDefinition, listIds: [String], hideCompletedBeforeMs: Int64?, nowMs: Int64, zone: String) throws  -> BoardRead
    
    /**
     * The tasks `definition` shows across the workspace, in board order.
     */
    func filterListTasks(workspaceId: String, definition: FilterDefinition, nowMs: Int64, zone: String) throws  -> [TaskRow]
    
    /**
     * The workspace's filter lists in sidebar order; not the built-in ones
     * (`builtin_filter_lists`).
     */
    func filterLists(workspaceId: String) throws  -> [FilterListRow]
    
    /**
     * Moves a filter list to `index` as one "Move Filter List" step.
     */
    func moveFilterList(id: String, index: UInt32, nowMs: Int64) throws 
    
    /**
     * Renames a filter list as one "Rename Filter List" step.
     */
    func renameFilterList(id: String, name: String, nowMs: Int64) throws 
    
    /**
     * Saves a filter list's name, icon, colour and rules as one "Edit Filter
     * List" step.
     */
    func updateFilterList(id: String, name: String, icon: String?, colorHex: String?, definition: FilterDefinition, nowMs: Int64) throws  -> FilterListRow
    
    /**
     * A window's schedule: `events` (from the agenda calendars) and the
     * timed tasks overlapping `[from_ms, to_ms)`, all-day events first,
     * then by start. An event that stands for a task is shown as the task.
     */
    func googleCalendarAgenda(events: [GoogleCalendarEvent], fromMs: Int64, toMs: Int64) throws  -> [GoogleCalendarAgendaEntry]
    
    /**
     * Starts a pass: None when two-way sync is off or another device holds
     * the lease, otherwise the calendar and where its feed was left.
     */
    func googleCalendarBeginPass(nowMs: Int64) throws  -> GoogleCalendarPass?
    
    /**
     * Merges a pass's changed events (every event when `full`) with the
     * workspace. Changes to tasks are one "Google Calendar" undo step;
     * the writes Google needs come back to be sent, each then handed to
     * [`Self::google_calendar_record_push`].
     */
    func googleCalendarReconcile(calendarId: String, events: [GoogleCalendarEvent], full: Bool, accessToken: String, nowMs: Int64, zone: String) throws  -> GoogleCalendarReconcile
    
    /**
     * Files a sent write's answer: `status` is the HTTP status of the last
     * request sent for it (`on_conflict`'s, when that was sent), `body`
     * what came back.
     */
    func googleCalendarRecordPush(push: GoogleCalendarPush, status: UInt16, body: String, nowMs: Int64) throws  -> GoogleCalendarPushOutcome
    
    /**
     * The account's calendar choices.
     */
    func googleCalendarSettings() throws  -> GoogleCalendarSettings
    
    /**
     * Stores the account's calendar choices. Choosing another two-way
     * calendar forgets the links to the old one's events, which stay there.
     */
    func setGoogleCalendarSettings(settings: GoogleCalendarSettings, nowMs: Int64) throws 
    
    /**
     * Where a calendar's feed carries on from; None starts it again.
     */
    func setGoogleCalendarSyncToken(calendarId: String, syncToken: String?, nowMs: Int64) throws 
    
    /**
     * Puts back one step taken back; see [`redo_step`].
     */
    func redoStep(id: String) throws  -> Bool
    
    /**
     * What Undo on one step would do; see [`step_undo_plan`].
     */
    func stepUndoPlan(id: String) throws  -> StepUndoPlan
    
    /**
     * Takes back one step, with the later ones only when it must; see
     * [`undo_step`].
     */
    func undoStep(id: String) throws  -> [String]
    
    /**
     * Settles the session left paused when the app last went away: closes
     * it, crediting its seconds at the moment it was paused, as one "Log
     * Daily Progress" step, or discards it. `resolveStaleFocusSession`.
     */
    func resolveStaleFocusSession(nowMs: Int64, zone: String, rolloverHour: UInt8, context: FocusContext) throws  -> StaleFocusOutcome
    
    /**
     * Today against the week, read and summed in the core.
     */
    func workProgress(nowMs: Int64, zone: String, firstWeekday: UInt8) throws  -> WorkProgressTotals
    
    /**
     * The newest session that has not finished.
     */
    func activeFocusSession() throws  -> SessionRow?
    
    /**
     * The live dailies in order.
     */
    func allDailies() throws  -> [DailyRow]
    
    /**
     * Every metadata row.
     */
    func allMetadata() throws  -> [MetadataRow]
    
    /**
     * Tasks completed since `since`, newest first.
     */
    func completedTasksSince(sinceMs: Int64, limit: Int64) throws  -> [TaskRow]
    
    /**
     * Where a completion now falls in its day and in a run of days.
     */
    func completionContext(nowMs: Int64, zone: String) throws  -> CompletionContext
    
    /**
     * One condition by id.
     */
    func condition(id: String) throws  -> ConditionRow?
    
    /**
     * How many open tasks require each condition, for those any does.
     */
    func conditionUsage(workspaceId: String) throws  -> [ConditionUsage]
    
    /**
     * A workspace's conditions, oldest first.
     */
    func conditions(workspaceId: String) throws  -> [ConditionRow]
    
    /**
     * One contribution by id.
     */
    func contribution(id: String) throws  -> ContributionRow?
    
    /**
     * A daily's contributions on the given days, oldest first.
     */
    func contributions(dailyId: String, dayKeys: [String]) throws  -> [ContributionRow]
    
    /**
     * The dailies the local day `day_ms` falls on shows, with their tasks and
     * that day's contributions.
     */
    func dailiesOn(dayMs: Int64, zone: String) throws  -> [DayDaily]
    
    /**
     * One daily by id, archived or not.
     */
    func daily(id: String) throws  -> DailyRow?
    
    /**
     * A task's live daily, if it has one.
     */
    func dailyForTask(taskId: String) throws  -> DailyRow?
    
    /**
     * One award by id.
     */
    func focusAward(id: String) throws  -> AwardRow?
    
    /**
     * Awards in `[from, to)`, newest first.
     */
    func focusAwardsBetween(fromMs: Int64, toMs: Int64) throws  -> [AwardRow]
    
    /**
     * What holds now, as last saved, or none if it never was.
     */
    func focusContext(workspaceId: String) throws  -> StoredFocusContext?
    
    /**
     * Points today, over the last seven days and ever.
     */
    func focusPointsSummary(todayMs: Int64, tomorrowMs: Int64, weekStartMs: Int64) throws  -> PointsSummary
    
    /**
     * A session's queue in order, with each task.
     */
    func focusQueue(sessionId: String) throws  -> [QueueEntry]
    
    /**
     * One session by id.
     */
    func focusSession(id: String) throws  -> SessionRow?
    
    /**
     * Whether any task is pinned in Today's order.
     */
    func hasManualFocusOrder() throws  -> Bool
    
    /**
     * Every saved board's columns.
     */
    func kanbanBoards() throws  -> [BoardBaseline]
    
    /**
     * Seconds logged per task.
     */
    func loggedWork() throws  -> [LoggedWork]
    
    /**
     * A task's metadata row, if it has one.
     */
    func metadata(taskId: String) throws  -> MetadataRow?
    
    /**
     * The metadata rows of the given tasks.
     */
    func metadataForTasks(taskIds: [String]) throws  -> [MetadataRow]
    
    /**
     * The metadata rows that carry planning or a start time.
     */
    func planningMetadata() throws  -> [MetadataRow]
    
    /**
     * Every preference.
     */
    func preferences() throws  -> [PreferenceRow]
    
    /**
     * The newest awards.
     */
    func recentFocusAwards(limit: Int64) throws  -> [AwardRow]
    
    /**
     * The conditions an open task in the workspace requires, by id, sorted.
     */
    func requiredConditionIds(workspaceId: String) throws  -> [String]
    
    /**
     * When tasks were completed in `[from, to)`.
     */
    func taskCompletionsBetween(fromMs: Int64, toMs: Int64) throws  -> [Int64]
    
    /**
     * Open and closed task counts.
     */
    func taskCounts() throws  -> TaskCounts
    
    /**
     * When tasks were created in `[from, to)`.
     */
    func taskCreationsBetween(fromMs: Int64, toMs: Int64) throws  -> [Int64]
    
    /**
     * Every task's planning, decoded and normalised in the core, so only
     * the tasks that have one cross, already parsed.
     */
    func taskPlanningValues() throws  -> [TaskPlanningEntry]
    
    /**
     * Tasks closed in `[from, to)`, oldest first.
     */
    func tasksClosedBetween(fromMs: Int64, toMs: Int64) throws  -> [TaskRow]
    
    /**
     * The open tasks that require a condition.
     */
    func tasksRequiringCondition(workspaceId: String, conditionId: String) throws  -> [RequiringTask]
    
    /**
     * The stored themes by id.
     */
    func themes() throws  -> [ThemeRow]
    
    /**
     * The metadata rows of waiting tasks and their follow-ups.
     */
    func waitingMetadata() throws  -> [MetadataRow]
    
    /**
     * Work blocks recorded in `[from, to)`.
     */
    func workBlocksBetween(fromMs: Int64, toMs: Int64) throws  -> [WorkBlockRow]
    
    /**
     * A task's work blocks, oldest first.
     */
    func workBlocksForTask(taskId: String) throws  -> [WorkBlockRow]
    
    /**
     * The reminders a device sets now (`reminders::reminders`).
     */
    func reminders(settings: ReminderSettings, nowMs: Int64, zone: String, days: UInt32, limit: UInt32) throws  -> [Reminder]
    
    /**
     * The progress charts over the `days` ending today, read and bucketed
     * in the core. `ReviewModel.readProgress`.
     */
    func reviewProgress(days: UInt32, nowMs: Int64, zone: String) throws  -> ReviewProgress
    
    /**
     * A task's subtasks and logged work, counted in the core.
     */
    func taskWorkFacts(taskId: String) throws  -> TaskWorkFacts
    
    /**
     * Forgets the outbox entries the server has accepted.
     */
    func acknowledgeSyncChanges(throughSeq: Int64) throws 
    
    /**
     * A combined scope's cards alone, packed, for an outline that draws
     * them flat. See `board::actionable_tasks`.
     */
    func actionableTasksPacked(listIds: [String]) throws  -> Data
    
    /**
     * Keeps a one-off copy of a repeating task at the dates `edit` gives,
     * and returns its id; see `tasks::add_occurrence_copy`. Called once the
     * move it answers is saved, it joins that move's step, relabelled "Keep
     * Both", so one undo takes back the move and the copy together
     * (`journal::begin_joining_last`); with no such step it is one of its own.
     */
    func addOccurrenceCopy(edit: EditorSnapshot, nowMs: Int64, zone: String) throws  -> String
    
    /**
     * Makes `task_id` wait on `blocked_by_task_id` as one "Add Blocker" step.
     * Returns whether it was new. A task waiting on itself, or an edge that
     * would close a cycle, is refused (`dependencies::add_blocker`).
     */
    func addTaskBlocker(taskId: String, blockedByTaskId: String, nowMs: Int64) throws  -> Bool
    
    /**
     * Links `url` to the task as one "Add Link" step, naming it `title`
     * with the file type `mime_type` when the picker knew them. Returns
     * whether the address is new; an address already there is renamed.
     */
    func addTaskLink(taskId: String, url: String, title: String?, mimeType: String?, nowMs: Int64) throws  -> Bool
    
    /**
     * Queues a task in a focus session.
     */
    func addToFocusQueue(sessionId: String, taskId: String, plannedSeconds: Int64?, nowMs: Int64) throws 
    
    /**
     * Every live commitment in the workspace.
     */
    func allCommitments() throws  -> [Commitment]
    
    /**
     * Copies a task's planning onto its subtasks as one step.
     */
    func applyPlanningToDescendants(taskId: String, nowMs: Int64, zone: String) throws 
    
    /**
     * Writes a pull into the workspace; whether anything changed.
     */
    func applyRemoteRows(rows: [IncomingRow], cursor: Int64, hlc: String?, nowMs: Int64) throws  -> Bool
    
    /**
     * Writes a gathered pull into the workspace in one transaction.
     */
    func applySyncPull(pull: SyncPull, wallMs: Int64, nowMs: Int64) throws  -> SyncPullOutcome
    
    /**
     * Archives a task's daily as one "Archive Daily" step.
     */
    func archiveDaily(taskId: String, nowMs: Int64) throws 
    
    /**
     * Ranks tasks in Today's focus order as one "Reorder Today" step.
     */
    func arrangeDay(orderedTaskIds: [String], nowMs: Int64) throws 
    
    /**
     * Pairs the store with a sync server.
     */
    func beginSync(deviceId: String, serverUrl: String) throws 
    
    /**
     * Every open task waiting on an open task: what a client draws dimmed.
     */
    func blockedTaskIds() throws  -> [String]
    
    /**
     * The workspace, made on first launch with its Inbox and conditions;
     * returns its id.
     */
    func bootstrap(nowMs: Int64) throws  -> String
    
    /**
     * Every open task whose start is still to come at `now_ms`: what a
     * client draws greyed in the buried section (`buried`).
     */
    func buriedTaskIds(nowMs: Int64) throws  -> [String]
    
    /**
     * Banks a running block's time.
     */
    func checkpointFocusSession(id: String, nowMs: Int64) throws 
    
    /**
     * The children of a task in a list, or its roots, in outline order;
     * none resting (`commitments::resting_task_ids`).
     */
    func childTasks(listId: String, parentTaskId: String?) throws  -> [TaskRow]
    
    /**
     * Un-ticks a day of a daily as one "Clear Daily" step.
     */
    func clearContribution(dailyId: String, dayMs: Int64, zone: String) throws 
    
    /**
     * Clears the focus order as one "Clear Focus Order" step.
     */
    func clearFocusOrder(nowMs: Int64) throws 
    
    /**
     * A combined scope's board — Everything's or a folder's — selected and
     * walked here, so only the rows it draws cross. See `board.rs`.
     */
    func combinedBoard(listIds: [String], hideCompletedBeforeMs: Int64?) throws  -> BoardRead
    
    /**
     * The live commitment a subtask carries, if it is one.
     */
    func commitment(taskId: String) throws  -> Commitment?
    
    /**
     * How many of a stacking commitment's missed appearances are still
     * owed on the day `now_ms` falls on; zero for one that vanishes.
     */
    func commitmentMissed(commitmentTaskId: String, nowMs: Int64, zone: String) throws  -> UInt32
    
    /**
     * The live commitments on a task, in the order of its subtasks.
     */
    func commitments(taskId: String) throws  -> [Commitment]
    
    /**
     * Turns a standalone list into a task in the Inbox; returns the task's id.
     */
    func convertListToTask(id: String, nowMs: Int64) throws  -> String
    
    /**
     * Creates a condition as one "New Condition" step; returns its id.
     */
    func createCondition(workspaceId: String, name: String, isLocation: Bool, nowMs: Int64) throws  -> String
    
    /**
     * Creates a condition under a category (none for uncategorised) as one
     * "New Condition" step; returns its id. Location makes it a place.
     */
    func createConditionInCategory(workspaceId: String, name: String, category: String?, nowMs: Int64) throws  -> String
    
    /**
     * Creates a folder as one "New Folder" step.
     */
    func createFolder(workspaceId: String, name: String, parentFolderId: String?, nowMs: Int64) throws  -> CreatedItem
    
    /**
     * Creates a list as one "New List" step.
     */
    func createList(workspaceId: String, name: String, folderId: String?, nowMs: Int64) throws  -> CreatedItem
    
    /**
     * Creates a task as one "New Task" step and returns its id.
     */
    func createTask(task: NewTask, nowMs: Int64) throws  -> String
    
    /**
     * Creates `task` and makes `task_id` wait on it, as one "New Blocker"
     * step (`dependencies::create_blocker`). Returns the new task's id.
     */
    func createTaskBlocker(taskId: String, task: NewTask, nowMs: Int64) throws  -> String
    
    /**
