/**
 * What went wrong in the core, as a client sees it.
 *
 * The field is `detail` rather than `message`: Kotlin's generated exception
 * would otherwise clash with `Throwable.message`.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Database(detail: String
    )
    case ForeignKeys(identifier: String, count: UInt32
    )
    case NoJournal
    case MissingTask(id: String
    )
    case MissingDaily(id: String
    )
    case MissingList(id: String
    )
    case MissingFolder(id: String
    )
    case SystemListIsPermanent
    case EmptyName
    case InvalidFolderMove
    case InvalidCondition
    case InvalidStatus(status: String
    )
    case InvalidSchedule
    case InvalidMinimum
    case EstimateRequired
    case InvalidDate
    case EditorConflict
    case InvalidVisibleRoot
    case DuplicateSourceId
    case NoActiveFocusTask
    case Unavailable
    case InvalidTaskMove
    case DependencyCycle
    case MissingFilterList(id: String
    )
    case InvalidFilter(detail: String
    )
    case File(detail: String
    )
    /**
     * A board column edit or a drop into a column that cannot be made.
     */
    case ColumnRefused(detail: String
    )
    case InvalidRecurrence(rule: String
    )
    /**
     * A Checkvist request the core refused to make, or an answer it could
     * not read (`checkvist.rs`).
     */
    case Checkvist(detail: String
    )
    /**
     * An estimate or minimum block typed in minutes that does not read as
     * one (`editor_draft.rs`).
     */
    case InvalidEstimate
    /**
     * A follow-up repeat outside 1 to 365 days (`waiting.rs`).
     */
    case InvalidFollowUpRepeat(days: UInt32
    )
    /**
     * A Google Calendar answer the core could not read
     * (`google_calendar.rs`).
     */
    case GoogleCalendar(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

